import json
for p in ['run_trace/galaxy_tool_run/request.json','run_trace/galaxy_tool_run_002/request.json','run_trace/galaxy_tool_run_002/validation_response.json','run_trace/galaxy_tool_run_003/validation_response.json']:
 print('\\nFILE',p)
 x=json.load(open(p))
 if 'validation_response' in p:
  # recursively find all dicts with key archives or selector group val
  def walk(v,path=''):
   if isinstance(v,dict):
    if 'archives' in v or v.get('selector')=='grouped_zip_archives': print(path, json.dumps(v)[:1800])
